-- mvtk/tiled/spawners/enemies.lua
-- Generated by splitting mvtk.tiled.object_spawner handlers by domain.

local OP = require "mvtk.tiled.object_props"
local EnemyOverrides = require "mvtk.enemies.enemy_overrides"

return function(H)
    local handlers = {}

    local M = H.M
    local Util = H.Util
    local TriggerPayloads = H.TriggerPayloads
    local CollectibleManager = H.CollectibleManager
    local EnemyManager = H.EnemyManager
    local TileSnap = H.TileSnap
    local get_gate_manager = H.get_gate_manager
    local get_boss_arena = H.get_boss_arena
    local get_tile_settings = H.get_tile_settings
    local get_room_world_offset = H.get_room_world_offset
    local to_bool = H.to_bool
    local resolve_rect_size_pixels = H.resolve_rect_size_pixels
    local rect_scale_from_size = H.rect_scale_from_size
    local resolve_breakable_swap_extent = H.resolve_breakable_swap_extent
    local parse_color_string = H.parse_color_string
    local non_empty_string = H.non_empty_string
    local resolve_boss_preset = H.resolve_boss_preset
    local resolve_boss_display_name = H.resolve_boss_display_name
    local get_props = H.get_props
    local make_id = H.make_id
    local world_point = H.world_point
    local world_rect = H.world_rect
    local spawn_factory = H.spawn_factory
    local spawn_collection = H.spawn_collection
    local post_collectible_tiled_overrides = H.post_collectible_tiled_overrides
    local apply_scale = H.apply_scale
    local make_scale = H.make_scale
    local send_tiled_props = H.send_tiled_props
    local log_spawn = H.log_spawn
    local log_register = H.log_register
    local get_type_prop = H.get_type_prop
    local record_error = H.record_error
    local normalize_gate_type_name = H.normalize_gate_type_name
    local normalize_gate_item_name = H.normalize_gate_item_name
    local resolve_chest_loot_table = H.resolve_chest_loot_table
    local print = H.print
    local polyline_registry = H.polyline_registry

function handlers.enemy(object, room_id)
    local props = get_props(object)
    local enemy_type = get_type_prop(props, "enemy_type", object)
    if not enemy_type then
        print("[OBJECT_SPAWNER] Enemy object missing enemy_type property and name:", object.id)
        return nil
    end

    local world_x, world_y, pos = world_point(object, room_id)

    local raw_overrides = {}
    for key, value in pairs(props) do
        raw_overrides[key] = value
    end
    raw_overrides.enemy_type = enemy_type
    raw_overrides.room_id = room_id
    raw_overrides.patrol_height_override = props.patrol_height
    local overrides = EnemyOverrides.normalize(raw_overrides)
    
    -- Create the enemy game object via collection factory
    local result = spawn_collection("enemy_factory", pos, {}, 1, "enemy")
    if not result then
        return nil
    end
    
    -- collectionfactory.create returns a table of created instances
    -- Find the main enemy instance URL
    local enemy_url = nil
    for _, id in pairs(result) do
        enemy_url = id
        break -- The first one should be the main enemy game object
    end
    
    if not enemy_url then
        print("[OBJECT_SPAWNER] No enemy instance returned from factory")
        return nil
    end
    
    -- Spawn enemy data in EnemyManager with overrides
    local spawn_id = EnemyManager.spawn_enemy(
        enemy_type,
        pos,
        overrides
    )
    
    if spawn_id then
        -- Register the created game object URL with the manager
        EnemyManager.register_enemy_instance(spawn_id, enemy_url)
        
        -- Send per-instance overrides directly to the enemy script
        -- This allows runtime configuration from Tiled properties
        overrides.spawn_id = spawn_id
        msg.post(enemy_url, hash("apply_tiled_overrides"), overrides)
        
        local elite_str = overrides.elite and " [ELITE]" or ""
        log_spawn("enemy", enemy_type, world_x, world_y,
            string.format("%s instance=%s", elite_str, tostring(enemy_url)))
    end

    -- Return both spawn_id and the game object URL for tracking
    return { spawn_id = spawn_id, instance_url = enemy_url }
end

    return handlers
end
